(4751690, 684821, 63503, '<td valign="top">Gorgeous</td>', 'Gorgeous', '2008-06-05 13:19:07.000000', NULL, 1),
(4751705, 685472, 63503, '<td valign="top">Top five for sure; should ribbon though. Great picture in all aspects.</td>', 'Top five for sure; should ribbon though. Great picture in all aspects.', '2008-06-05 13:23:11.000000', NULL, 1),
(4751706, 685255, 63503, '<td valign="top">Great capture !!</td>', 'Great capture !!', '2008-06-05 13:24:14.000000', NULL, 1),
(4751745, 684894, 63503, '<td valign="top">Fantastic picture!!</td>', 'Fantastic picture!!', '2008-06-05 13:40:21.000000', NULL, 1),
(4751784, 684894, 93765, '<td valign="top">Wow. Technically and visually very good indeed. Emotionally very creepy. I don''t like the expression of either of them, but for diametrically different reasons. Can''t help the feeling, that the horse may not sign the "mutually beneficial" part of the partnership. The ice cold, almost ruthless expression of the jockey says it all. Not a shot to promote horse racing, but a splendid one for animal activists. Congratulations for catching such a unique moment!</td>', 'Wow. Technically and visually very good indeed. Emotionally very creepy. I don''t like the expression of either of them, but for diametrically different reasons. Can''t help the feeling, that the horse may not sign the "mutually beneficial" part of the partnership. The ice cold, almost ruthless expression of the jockey says it all. Not a shot to promote horse racing, but a splendid one for animal activists. Congratulations for catching such a unique moment!', '2008-06-05 14:03:14.000000', NULL, 1),
(4751795, 685472, 54566, '<td valign="top">too good. 10.</td>', 'too good. 10.', '2008-06-05 14:11:41.000000', NULL, 1),
(4751803, 685065, 63750, '<td valign="top">Really great.  The contrast works great here.</td>', 'Really great.  The contrast works great here.', '2008-06-05 14:14:34.000000', NULL, 1),
(4751804, 685248, 63750, '<td valign="top">This is a magnificent shot. Surely a ribbon winner!</td>', 'This is a magnificent shot. Surely a ribbon winner!', '2008-06-05 14:14:59.000000', NULL, 1),
(4751807, 685257, 63750, '<td valign="top">Hilarious! Can''t get human models to make faces that great! Well done.</td>', 'Hilarious! Can''t get human models to make faces that great! Well done.', '2008-06-05 14:15:59.000000', NULL, 1),
(4751816, 685256, 93765, '<td valign="top">Now there''s a perfect case of "mutually beneficial"! Emphasis on "mutually", as in excluding Joe Public. You got me reaching for my soap box, head full of angles on that particular topic, but this is not the place for it. <br/>The picture captures the hectical hysteria of a rally very well.</td>', 'Now there''s a perfect case of "mutually beneficial"! Emphasis on "mutually", as in excluding Joe Public. You got me reaching for my soap box, head full of angles on that particular topic, but this is not the place for it. The picture captures the hectical hysteria of a rally very well.', '2008-06-05 14:18:08.000000', NULL, 1),
(4751837, 683830, 93765, '<td valign="top">Fun idea! A bit of a perpetuum mobile, though. Lots of bits and pieces that might have been solved differently, but that could have ruined the spontaneity.</td>', 'Fun idea! A bit of a perpetuum mobile, though. Lots of bits and pieces that might have been solved differently, but that could have ruined the spontaneity.', '2008-06-05 14:31:01.000000', NULL, 1),
