(4754382, 685454, 90777, '<td valign="top">Would love to have seen the pitcher in action, rather than a bunch of guys just standing around.</td>', 'Would love to have seen the pitcher in action, rather than a bunch of guys just standing around.', '2008-06-06 15:24:28.000000', NULL, 1),
(4754387, 683140, 90777, '<td valign="top">Would much prefer to see them running towards you, so that then we can see their cute fluffy faces rasther than their hairy backsides ;-)  Good composition and well done for giving them space to run into the rest of the frame.  Also like the leading lines of the path.</td>', 'Would much prefer to see them running towards you, so that then we can see their cute fluffy faces rasther than their hairy backsides ;-)  Good composition and well done for giving them space to run into the rest of the frame.  Also like the leading lines of the path.', '2008-06-06 15:27:41.000000', NULL, 1),
