(4761828, 684948, 811, '<td valign="top">This is one of those shots that I really like, but cannot clearly define why I like it.  Nice work.</td>', 'This is one of those shots that I really like, but cannot clearly define why I like it.  Nice work.', '2008-06-10 17:19:03.000000', NULL, 1),
(4761831, 685385, 811, '<td valign="top">I think converting this to a high contrast bw would have made it more compelling.  As it is, the skin tones and the sink (?) are a bit too close in color tones.  The blue glove is a nice contrast, though.</td>', 'I think converting this to a high contrast bw would have made it more compelling.  As it is, the skin tones and the sink (?) are a bit too close in color tones.  The blue glove is a nice contrast, though.', '2008-06-10 17:20:12.000000', NULL, 1),
(4761832, 684520, 811, '<td valign="top">The crop is a bit too "narrow" left to right, I think.  It feels like it needs to be "opened" up a bit more.</td>', 'The crop is a bit too "narrow" left to right, I think.  It feels like it needs to be "opened" up a bit more.', '2008-06-10 17:20:42.000000', NULL, 1),
