(4762712, 685248, 49804, '<td valign="top">Congrats on the new personal best, very well deserved score. Great composition, love the colors and lighting, really nice job, adding to faves.</td>', 'Congrats on the new personal best, very well deserved score. Great composition, love the colors and lighting, really nice job, adding to faves.', '2008-06-11 01:05:34.000000', NULL, 0),
(4762715, 685381, 67697, '<td valign="top">omg I thought this was sooooooo funny.  Glad to see this is yours!  Way too cool.  Great outfits and expressions.  Love the processing too.  Congrats on a great score!</td>', 'omg I thought this was sooooooo funny.  Glad to see this is yours!  Way too cool.  Great outfits and expressions.  Love the processing too.  Congrats on a great score!', '2008-06-11 01:05:41.000000', NULL, 0),
(4762720, 685248, 32872, '<td valign="top">Perfect timing all the way around for a ribbon!  Congratulations!</td>', 'Perfect timing all the way around for a ribbon!  Congratulations!', '2008-06-11 01:06:52.000000', NULL, 0),
