(4762723, 685472, 90387, '<td valign="top">I Love this image, and was one of your many 10''s.  So glad to see this on the front page!  Congratulations!</td>', 'I Love this image, and was one of your many 10''s.  So glad to see this on the front page!  Congratulations!', '2008-06-11 01:07:07.000000', NULL, 0),
(4762724, 685065, 49804, '<td valign="top">Great job with this one, really nice timing to get both of them in almost the exact position. Great job and congrats on the ribbon.</td>', 'Great job with this one, really nice timing to get both of them in almost the exact position. Great job and congrats on the ribbon.', '2008-06-11 01:07:16.000000', NULL, 0),
