(4762737, 684729, 49804, '<td valign="top">congrats jeff, nice score, and another month of slaughtering me, nice shot man, keep it up.</td>', 'congrats jeff, nice score, and another month of slaughtering me, nice shot man, keep it up.', '2008-06-11 01:09:46.000000', NULL, 0),
(4762756, 685472, 63812, '<td valign="top">Congratulations, Alfredo! Very deserved recognition for a new sample of your photographic eye.  <br/></td>', 'Congratulations, Alfredo! Very deserved recognition for a new sample of your photographic eye.  ', '2008-06-11 01:13:15.000000', NULL, 0),
(4762758, 684586, 14012, '<td valign="top">First entry back and made the top 20. Nice work Joel! I was waiting to see what you entered.</td>', 'First entry back and made the top 20. Nice work Joel! I was waiting to see what you entered.', '2008-06-11 01:13:59.000000', NULL, 0),
