INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4767386, 685472, 66597, '<td valign="top">Alfredo, think photo is absolutely AMAZING! I''m really glad you didn''t clone out the little area of roof, as I think it adds atmosphere and sense of place to the image. one of the most evocative I''ve seen for a long time. Congratulations!</td>', 'Alfredo, think photo is absolutely AMAZING! I''m really glad you didn''t clone out the little area of roof, as I think it adds atmosphere and sense of place to the image. one of the most evocative I''ve seen for a long time. Congratulations!', '2008-06-13 10:42:41.000000', NULL, 0),
